/**
 * At the Temple Gate
 * ------------------
 * The Lord tells Jeremiah to stand at the temple gate and cry: trust not in the temple itself; do justice, hear the widow's plea. Stage: a temple gate at midday, a lone voice in a busy court, the poor and the blind at the steps; the stone of the temple and the people at its feet.
 *
 * Palette 0x2a1a10 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jeremiah-kit.js.
 */

import { THREE, createScene, cityGate, house, temple, column, pillar, person, crowd } from './jeremiah-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1191146499, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-17, 0, -58], { name: 'city', r: [0, -0.01, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* temple: colonnade and glowing doorway */
    const templeG = W.grp(group, [0, 0, -46], { name: 'temple', r: [0, -0.14, 0] });
    temple(W, templeG, 0, 0, 0, 1.1, { stone: 0x070402, trim: 0x1d120b });
    W.backdrop(templeG);

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x372215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x301e12, wrapTrim: 0x1d120b, beard: 'long', staff: 'planted', bend: 0.02, ry: -0.20, s: 1.02 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x301e12, wrapTrim: 0x1d120b, beard: 'long', staff: 'planted', bend: 0.02, ry: -0.63, s: 1.03 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x301e12, wrapTrim: 0x1d120b, beard: 'long', staff: 'planted', bend: 0.02, ry: -0.29, s: 1.18 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 18, 70, 44, [0x2a1a10, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    return W.finish();
}

export default { build };
